# ---- Step 2 (session 3): readings the site lacks, and missing English
import copy
def ADD(file,path,new,src,why): FX.append({"file":file,"op":"add","path":path,"old":None,"new":new,"src":src,"why":why})
RD=F.A.RD
DRN='English: Douay-Rheims verses (the site\'s English for readings; the St Dominic Missal 1959 readings are not in the repo), cut/adapted to the Missal\'s Latin'
def rd(type_,ref,title,title_en,la,en,src): return {"type":type_,"ref":ref,"title":title,"title_en":title_en,"la":la,"en":en,"p33":None,"src":src+'; '+DRN}
LW=("Léctio libri Sapiéntiæ.","Lesson from the Book of Wisdom.")
GM=("Sequéntia sancti Evangélii secúndum Matthǽum.","Continuation of the holy Gospel according to Matthew.")
GL=("Sequéntia sancti Evangélii secúndum Lucam.","Continuation of the holy Gospel according to Luke.")
def cp(k,i,src):
    r=copy.deepcopy(RD[k][i]); r['p33']=None; r['src']=src+'; text as for '+k+' (checked on the scan; same printing)'; r.pop('do',None); r.pop('do_sim',None); r.pop('la_fixed',None); return r
